def move_one_ball(arr):
    n = len(arr)
    if (n == 0): 
        return True
    if (arr[n - 1] < arr[0]): 
        return False
    left = 0
    right = n - 1
    while (left <= right):
        mid = int(left + (right - left) / 2)
        if (mid > right):
            break
        if (arr[mid] >= arr[left]):
            left = mid + 1
        elif (arr[mid] < arr[right]):
            right = mid - 1
        else:
            left = mid + 1
            right = mid - 1
    return True

